"import yfinance as yf
from datetime import datetime

def format_inr_cr(num):
    if num is None:
        return "N/A"
    try:
        val = float(num)
        # If in rupees and >= 1 Cr
        if abs(val) >= 1e7:
            cr = val / 1e7
            return f"₹{int(round(cr)):,} Cr"
        elif abs(val) >= 1e5:
            return f"₹{int(round(val / 1e5)):,} Lakh"
        return f"₹{val:,.2f}"
    except Exception:
        return str(num)

for sym in ["INFY", "WIPRO", "TCS"]:
    ticker = yf.Ticker(f"{sym}.NS")
    info = ticker.info or {}
    print(f"=== {sym} ===")
    print("Name:", info.get("longName"))
    print("Rev:", format_inr_cr(info.get("totalRevenue")))
    print("Op Margins:", f"{round(float(info.get('operatingMargins', 0))*100, 1)}%" if info.get("operatingMargins") else "N/A")
    print("Net Profit:", format_inr_cr(info.get("netIncomeToCommon")))
    print("FCF:", format_inr_cr(info.get("freeCashflow")))
    print("OCF:", format_inr_cr(info.get("operatingCashflow")))
"

