def _fmt_cr(val) -> str:
    if val is None or val == 0:
        return "₹0 Cr"
    try:
        f_val = float(val)
        if abs(f_val) >= 1e7:
            return f"₹{int(round(f_val / 1e7)):,} Cr"
        elif abs(f_val) >= 1e5:
            return f"₹{int(round(f_val / 1e5)):,} Lakh"
        return f"₹{int(round(f_val)):,}"
    except Exception:
        return str(val)


def _fmt_pct(val) -> str:
    if val is None:
        return "N/A"
    try:
        f = float(val)
        if abs(f) > 1.0:
            return f"{round(f, 1)}%"
        return f"{round(f * 100, 1)}%"
    except Exception:
        return str(val)


class ResearchEngine:
